import pandas as pd
import numpy as np

# Load the data
waste_data = pd.read_csv('getisord_2021_waste.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Replace the missing value in the Waste_value column with the median of the non-missing values
waste_data['Waste_value'] = waste_data['Waste_value'].fillna(waste_data['Waste_value'].median())

# Get the list of unique boroughs
boroughs = waste_data['borough'].unique()

# Create a dictionary to store the neighbors of each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a dictionary to store the combined local areas
combined_areas = {}
for borough in boroughs:
    combined_areas[borough] = waste_data[waste_data['borough'] == borough]['Waste_value'].values[0]
    for neighbor in neighbors[borough]:
        if neighbor in combined_areas:
            combined_areas[borough] += waste_data[waste_data['borough'] == neighbor]['Waste_value'].values[0]

# Calculate the mean and standard deviation of the combined local areas
mean_combined = np.mean(list(combined_areas.values()))
std_combined = np.std(list(combined_areas.values()))

# Calculate the z-scores for each combined local area
z_scores = {}
for borough, value in combined_areas.items():
    z_scores[borough] = (value - mean_combined) / std_combined

# Identify the hot and cold spots
hot_spots = {borough: value for borough, value in z_scores.items() if value > 1.96}
cold_spots = {borough: value for borough, value in z_scores.items() if value < -1.96}

# Report the results
data_points_used = len(waste_data)
results = []
for borough, value in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={value}, gi_value={value})")
for borough, value in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={value}, gi_value={value})")
if not results:
    results = ['none']
print(f"FINAL ANSWER: {', '.join(results)}")
print(f"data_points_used = {data_points_used}")
